import{_ as s,o as i,c as e,a2 as t}from"./chunks/framework.BvlN9b-o.js";const c=JSON.parse('{"title":"查询筛选与分页合同","description":"","frontmatter":{"docLocale":"zh","counterpart":"/en/tutorials/search-preview","contentType":"guide","prev":false,"next":false},"headers":[],"relativePath":"tutorials/search-preview.md","filePath":"tutorials/search-preview.md"}'),h={name:"tutorials/search-preview.md"};function n(r,a,l,p,k,d){return i(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="查询筛选与分页合同" tabindex="-1">查询筛选与分页合同 <a class="header-anchor" href="#查询筛选与分页合同" aria-label="Permalink to &quot;查询筛选与分页合同&quot;">​</a></h1><p>目标：给自己的列表 API 增加有界筛选和稳定分页，同时避免泄露无权资源。前提是已有<a href="./personal-documents">持久业务</a>及资源权限策略。知识库的搜索和 Markdown 预览是参考实现，预览属于可选客户端能力。</p><h2 id="从协议到查询" tabindex="-1">从协议到查询 <a class="header-anchor" href="#从协议到查询" aria-label="Permalink to &quot;从协议到查询&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/src/modules/knowledge/mod.rs" target="_blank" rel="noreferrer">DocumentsQuery</a>定义 <code>knowledge_base_id / q / limit / cursor</code>：不传库 ID 时只查个人库；<code>q</code> 最多 200 字符、去首尾空白、拒绝 NUL；<code>limit</code> 默认 50、上限 100。列表只返回摘要和 <code>next_cursor / has_more</code>，不返回正文或全表总数。</p><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/src/modules/knowledge/application.rs" target="_blank" rel="noreferrer">实际查询</a>的关键形状如下，完整 SQL 还包含当前权限、未删除状态和库范围：</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">AND</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ($</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">timestamptz</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> IS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> NULL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> OR</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">d</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">created_at</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">d</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ($</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">timestamptz</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, $</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">::uuid))</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">AND</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> d</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">title</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ILIKE $</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">6</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ORDER BY</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> d</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">created_at</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> DESC</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">d</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">id</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> DESC</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">LIMIT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span></span></code></pre></div><p>输入先转义 LIKE 的 <code>%</code>、<code>_</code>、反斜杠，再绑定参数。因此 <code>100%_</code> 是字面子串，不是用户控制的通配符。权限、筛选和分页共同进入数据库查询，不先查询私密标题再交给客户端过滤。</p><h2 id="游标是位置" tabindex="-1">游标是位置 <a class="header-anchor" href="#游标是位置" aria-label="Permalink to &quot;游标是位置&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/crates/app/src/modules/knowledge/pagination.rs" target="_blank" rel="noreferrer">Cursor</a>绑定账号、库范围、排序、规范化关键词摘要与末条位置；改变账号/范围/关键词就重新从第一页查询。每页独立授权；cursor 不是凭据，也不提供跨页数据库快照。</p><p>多取一条判断下一页，避免无限列表。客户端 Query key 使用相同身份/范围/筛选，参考 View 最多保留十页；无效或混用 cursor 返回结构化 400，不退回全表查询。</p><h2 id="验证后端结果" tabindex="-1">验证后端结果 <a class="header-anchor" href="#验证后端结果" aria-label="Permalink to &quot;验证后端结果&quot;">​</a></h2><p>从仓库根目录执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/test-backend.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --test</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> knowledge</span></span></code></pre></div><p><a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/apps/api/tests/knowledge.rs" target="_blank" rel="noreferrer">HTTP 检查</a>验证 <code>%/_</code> 字面搜索、顺序、跨账号不可见、筛选绑定和撤权后的翻页拒绝。自己的列表至少验证两页无重复、变更筛选后旧 cursor 拒绝、无权标题不出现在结果、limit 上限和非法输入。</p><h2 id="可选-markdown-客户端" tabindex="-1">可选 Markdown 客户端 <a class="header-anchor" href="#可选-markdown-客户端" aria-label="Permalink to &quot;可选 Markdown 客户端&quot;">​</a></h2><p>需要内容预览时复用<a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/packages/views/src/knowledge/markdown-content.tsx" target="_blank" rel="noreferrer">安全渲染参考</a>：<code>react-markdown / remark-gfm / rehype-sanitize</code>，禁止 raw HTML，保留 URL 协议过滤。服务端不抓取外链，外部图片不自动加载；附件通过<a href="./attachments">授权引用</a>显示，不保存签名 URL。</p><p>预览按需加载，草稿与已保存资源分开，超出正文预算保留输入并拒绝预览/提交。它不是后端权限过滤的替代。自己的文本搜索规则可以不同，但需同时更新 DTO、SQL、cursor 和测试；接着实现<a href="./edit-conflicts">版本条件更新</a>。</p><hr><p>源码版本：<code>88c22a67f072</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/88c22a67f072afb7f7e64ebfb5fc0585b56ca1de/docs/tutorials/05-search-preview.md" target="_blank" rel="noreferrer">本页 Markdown</a></p>`,19)])])}const g=s(h,[["render",n]]);export{c as __pageData,g as default};
